export const CHECKOV_ALL_RESOURCE_SCAN_RULES = Object.freeze(
  CHECKOV_ALL_RESOURCE_SCAN_RULES_DATA.map((rule) => Object.freeze(rule))
);

export const CHECKOV_ALL_RESOURCE_RULESET = Object.freeze({
  name: "checkov/all-resource-scans",
  displayName: "Checkov All Resource Scans",
  ruleCount: CHECKOV_ALL_RESOURCE_SCAN_RULES.length,
  ruleIds: Object.freeze(["CKV_*", "CKV2_*"]),
  iacTypes: Object.freeze([
    "Terraform",
    "Kubernetes",
    "CloudFormation",
    "ARM",
    "Bicep",
    "Ansible",
    "Dockerfile",
    "Helm",
    "Serverless"
  ])
});

const RULES_BY_ID = new Map();
const RULES_BY_ENTITY = new Map();

for (const rule of CHECKOV_ALL_RESOURCE_SCAN_RULES) {
  const idBucket = RULES_BY_ID.get(rule.id) ?? [];
  idBucket.push(rule);
  RULES_BY_ID.set(rule.id, idBucket);

  for (const key of entityKeys(rule.entity)) {
    const entityBucket = RULES_BY_ENTITY.get(key) ?? [];
    entityBucket.push(rule);
    RULES_BY_ENTITY.set(key, entityBucket);
  }
}

export function getRuleSetMetadata(name) {
  if (name !== CHECKOV_ALL_RESOURCE_RULESET.name) return null;
  return CHECKOV_ALL_RESOURCE_RULESET;
}

export function getCheckovRuleById(id) {
  return RULES_BY_ID.get(String(id ?? "")) ?? [];
}

export function findCheckovRulesForLine(line, options = {}) {
  const text = String(line ?? "");
  const limit = Number(options.limit ?? 25);
  const iacType = normalizeIacType(options.iacType);
  const matches = new Map();

  for (const id of text.match(/\bCKV2?_[A-Z0-9_]+\b/g) ?? []) {
    for (const rule of RULES_BY_ID.get(id) ?? []) {
      if (matchesIac(rule, iacType)) matches.set(ruleKey(rule), rule);
    }
  }

  for (const token of tokensFrom(text)) {
    for (const rule of RULES_BY_ENTITY.get(token) ?? []) {
      if (matchesIac(rule, iacType)) matches.set(ruleKey(rule), rule);
      if (matches.size >= limit) return [...matches.values()];
    }
  }

  return [...matches.values()].slice(0, limit);
}

export function inferIacTypeFromPath(filePath) {
  const p = String(filePath ?? "").replace(/\\/g, "/").toLowerCase();
  if (p.endsWith("dockerfile") || p.includes("/dockerfile")) return "Dockerfile";
  if (p.endsWith(".tf") || p.endsWith(".tfvars")) return "Terraform";
  if (p.endsWith(".bicep")) return "Bicep";
  if (p.endsWith(".template")) return "CloudFormation";
  if (p.endsWith("chart.yaml") || p.endsWith("values.yaml")) return "Helm";
  if (p.endsWith("serverless.yml") || p.endsWith("serverless.yaml")) return "Serverless";
  if (p.includes("ansible") || p.includes("playbook") || p.includes("/roles/")) return "Ansible";
  if (p.endsWith(".yaml") || p.endsWith(".yml")) return "Kubernetes";
  if (p.endsWith(".json")) return "ARM";
  return "";
}

function entityKeys(entity) {
  const value = String(entity ?? "").trim();
  if (!value) return [];
  return [...new Set([
    value,
    value.toLowerCase(),
    value.replace(/[^A-Za-z0-9_:-]/g, ""),
    value.toLowerCase().replace(/[^a-z0-9_:-]/g, "")
  ].filter(Boolean))];
}

function tokensFrom(text) {
  return new Set(
    (String(text).match(/[A-Za-z][A-Za-z0-9_:-]*/g) ?? [])
      .flatMap((token) => [token, token.toLowerCase()])
  );
}

function normalizeIacType(iacType) {
  return String(iacType ?? "").trim().toLowerCase();
}

function matchesIac(rule, normalizedIacType) {
  if (!normalizedIacType) return true;
  const ruleIac = String(rule.iac ?? "").toLowerCase();
  if (!ruleIac) return true;
  if (ruleIac.includes(normalizedIacType)) return true;
  if (normalizedIacType === "helm") return ruleIac.includes("kubernetes") || ruleIac.includes("helm");
  if (normalizedIacType === "serverless") return ruleIac.includes("serverless") || ruleIac.includes("cloudformation");
  if (normalizedIacType === "bicep") return ruleIac.includes("bicep") || ruleIac.includes("arm");
  return false;
}

function ruleKey(rule) {
  return [rule.id, rule.entity, rule.iac].join(":");
}
